import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const g=JSON.parse('{"title":"Guitarify","description":"","frontmatter":{},"headers":[],"relativePath":"generators/GUITARIFY.md","filePath":"generators/GUITARIFY.md"}'),s={name:"generators/GUITARIFY.md"};function d(n,t,h,i,c,l){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="guitarify" tabindex="-1">Guitarify <a class="header-anchor" href="#guitarify" aria-label="Permalink to &quot;Guitarify&quot;">​</a></h1><p>A keyboard plays a chord as a stack of notes struck together and held. A guitar plays the same chord across six strings, one note a string, and a hand strikes those strings in a rhythm: a strum down, a strum up, a muted strum, the bass string, one string picked alone. Guitarify plays a clip&#39;s chords and notes that way, on any instrument, so a pattern that is only a row of chords becomes a strummed or picked part.</p><p>Guitarify has two sections, and each can be switched off. Shape is the fretting hand, which decides the notes of each chord. Strokes is the other hand, which decides when each string sounds.</p><h2 id="shape" tabindex="-1">Shape <a class="header-anchor" href="#shape" aria-label="Permalink to &quot;Shape&quot;">​</a></h2><p>Shape holds each chord as a hand can hold it: at most one note on each string, every note within four frets of the hand&#39;s position, and the chord&#39;s lowest written note in the bass wherever a string can reach it. C, E and G written close together become C, E, G, C and E across five strings, the open C chord. A hand with too few strings for a chord leaves the fifth out first and the root out last.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Shape chords</td><td>Switches the section on or off. Off leaves every chord as written.</td></tr><tr><td>Tuning</td><td>The open strings: standard, drop D, open G, open D or DADGAD.</td></tr><tr><td>Position</td><td>Where the hand is: &quot;open&quot;, which uses the open strings and the first three frets, or a fret from 1 to 12, which uses that fret and the three above.</td></tr><tr><td>Capo</td><td>The fret a capo clamps, which raises every string.</td></tr><tr><td>Strings</td><td>How many strings are played, from 3 to 6, counted from the highest, so 4 leaves out the two lowest.</td></tr><tr><td>Single notes</td><td>What becomes of a step that holds one note: &quot;leave&quot; keeps the note; &quot;power chord&quot; plays the root, the fifth above and the octave on the low strings; &quot;scale chord&quot; plays the chord the note&#39;s place in the scale builds.</td></tr></tbody></table><h2 id="strokes" tabindex="-1">Strokes <a class="header-anchor" href="#strokes" aria-label="Permalink to &quot;Strokes&quot;">​</a></h2><p>Strokes plays a bar of strokes, one stroke a cell, on whatever chord or note sounds at that moment. The bar follows the song&#39;s bars and goes round for as long as the clip plays. A single note is played by every stroke.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Play strokes</td><td>Switches the section on or off. Off leaves each chord struck once, where the pattern wrote the chord.</td></tr><tr><td>Bar</td><td>The bar of strokes, shown by the name of the ready-made bar the cells match, or as &quot;custom&quot;. ENTER opens the bar&#39;s editor.</td></tr><tr><td>Let ring</td><td>A struck string sounds until a later stroke strikes the same string or the chord ends, as picked chords do. Off stops every string at the next stroke.</td></tr><tr><td>Spread</td><td>The time between one string of a strum and the next, in milliseconds whatever the tempo.</td></tr><tr><td>Fade</td><td>How much quieter the last string of a strum is than the first, up to 50%.</td></tr><tr><td>Loose timing</td><td>How much each gap between strings varies, up to 50%, drawn from the song&#39;s seed.</td></tr><tr><td>Upstroke strings</td><td>How many of the top strings an upstroke catches, or &quot;all&quot;.</td></tr><tr><td>Restart</td><td>When the bar starts over, as <a href="./../GENERATORS#restart">Generators</a> describes.</td></tr></tbody></table><p>Guitarify&#39;s Spread, Fade, Loose timing and Upstroke strings are Guitarify&#39;s own. The <a href="./STRUM">Strum</a> generator and the Strum sections of a track and a clip are separate and unchanged.</p><h2 id="bar-editor" tabindex="-1">Bar Editor <a class="header-anchor" href="#bar-editor" aria-label="Permalink to &quot;Bar Editor&quot;">​</a></h2><p>The bar&#39;s editor shows one cell a column, with the stroke above and the accent below. Left and Right move along the cells, <code>[</code> and <code>]</code> change the stroke under the cursor, Space or ENTER accents the cell, <code>I</code> inserts a cell, <code>D</code> removes one, <code>S</code> steps the cell length and <code>R</code> picks a ready-made bar. A bar holds up to 32 cells.</p><table tabindex="0"><thead><tr><th>Stroke</th><th style="text-align:center;">Drawn</th><th>What plays</th></tr></thead><tbody><tr><td>nothing</td><td style="text-align:center;"><code>—</code></td><td>Nothing new: what was struck before sounds on.</td></tr><tr><td>down</td><td style="text-align:center;"><code>↓</code></td><td>Every string, low to high.</td></tr><tr><td>up</td><td style="text-align:center;"><code>↑</code></td><td>The top strings, high to low.</td></tr><tr><td>mute</td><td style="text-align:center;"><code>x</code></td><td>Every string, short and quiet, as a palm-muted or scratched strum.</td></tr><tr><td>bass</td><td style="text-align:center;"><code>B</code></td><td>The lowest string.</td></tr><tr><td>alt bass</td><td style="text-align:center;"><code>A</code></td><td>The fifth of the chord where a string plays one, and otherwise the second lowest string.</td></tr><tr><td>string 1 to string 4</td><td style="text-align:center;"><code>1</code> to <code>4</code></td><td>One string, counted from the highest. A string the chord lacks plays the nearest string the chord has.</td></tr></tbody></table><p>Where a bar has any accented cell, the strokes without an accent play a little softer.</p><p>The ready-made bars are folk strum, boom-chick, travis pick, crosspick, four to the bar, backbeat, boogie, scratch, all down, chug, gallop, thrash, tremolo, chime, roll up, roll down and held. Picking one replaces the strokes, the accents and the cell length together, and the bar can be edited from there. A rolled chord is the roll up or the roll down bar with Let ring on.</p><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Add a Guitarify to a chain, as <code>guitarify: name</code>, and give clips that chain. A Progression before the Guitarify in the same chain moves one written chord through a song&#39;s chords, and the Guitarify then plays each. <code>examples/learning/23_guitarify.yml</code> plays twenty short scenes, each a way a guitar is played, from one pattern of chords a scene.</p>',17)])])}const u=e(s,[["render",d]]);export{g as __pageData,u as default};
